#!/usr/bin/env python3
"""Shortest path length S->E on a '#'/'.' grid (4-neighbour). Prints length or -1."""
import sys


def solve(data):
    lines = data.split(b"\n")
    lines = [ln.rstrip(b"\r") for ln in lines]
    while lines and not lines[-1]:
        lines.pop()
    if not lines:
        return -1
    w = max(len(ln) for ln in lines)
    wp = w + 1  # one wall column between rows
    wall = b"#" * wp
    parts = [wall]
    for ln in lines:
        parts.append(ln.ljust(wp, b"#"))
    parts.append(wall)
    g = bytearray(b"".join(parts))
    s = g.find(b"S")
    e = g.find(b"E")
    if s < 0 or e < 0:
        return -1
    if s == e:
        return 0
    g[s] = 35
    frontier = [s]
    d = 0
    while frontier:
        d += 1
        nxt = []
        app = nxt.append
        for p in frontier:
            q = p - 1
            if g[q] != 35:
                if q == e:
                    return d
                g[q] = 35
                app(q)
            q = p + 1
            if g[q] != 35:
                if q == e:
                    return d
                g[q] = 35
                app(q)
            q = p - wp
            if g[q] != 35:
                if q == e:
                    return d
                g[q] = 35
                app(q)
            q = p + wp
            if g[q] != 35:
                if q == e:
                    return d
                g[q] = 35
                app(q)
        frontier = nxt
    return -1


if __name__ == "__main__":
    print(solve(sys.stdin.buffer.read()))
